// Meme swarms on screen: the strip on a meme result (a dot timeline, the two-word answer, a few
// chips), the "Spreading now" wall on the home page and the page of one live picture (opened in-app:
// a wall tile or "Live on Bluesky" calls the page's `onLink`, main.ts keeps the history).
// Pictures first, almost no words: a verdict describes the group of posts, never one account, so
// no verdict or flag ever sits next to a handle.
import { axisLabels, fetchSwarmDetail, fetchSwarmWall, firstWords, GROUP_FILLS, layoutTimeline, postStamp, swarmAria, swarmChips, VERDICT, type SwarmCard, type SwarmDetail, type SwarmReport } from "../data/swarm";
import { IMAGE_TYPES } from "../data/lookup";
import { esc } from "./format";
import { icon } from "./icons";
import "./swarm.css";

const PITCH = 10; // viewBox units per dot column / row
const COLS = 48;
const COLS_NARROW = 32; // a phone: fewer, bigger dots, while they fill at most half the grid (a shape, not a solid block)
const ROWS = 10;
const columns = (n: number) => (n <= (COLS_NARROW * ROWS) / 2 && typeof matchMedia === "function" && matchMedia("(max-width: 600px)").matches ? COLS_NARROW : COLS);

/** a link to the page of one live picture; the dev mock flag rides along */
export function swarmHref(id: string): string {
  const params = new URLSearchParams({ swarm: id });
  const here = new URLSearchParams(location.search);
  const mock = here.get("mockSwarm") ?? (here.has("mockLookup") ? "" : null);
  if (import.meta.env.DEV && mock != null) params.set("mockSwarm", mock);
  return `?${params}`;
}

const epoch = (iso: string | null | undefined) => (iso ? Date.parse(iso) / 1000 : NaN);

/** the dot timeline: one dot per sighting, the burst on a band of the verdict's colour */
function plot(report: SwarmReport): string {
  const points = (report.timeline ?? []).filter((p) => p && Number.isFinite(p.t));
  // no readable time at all: no plot (an axis of "NaN" says nothing)
  if (!points.length) return "";
  const cols = columns(points.length);
  const { dots, burst } = layoutTimeline(points, { cols, rows: ROWS });
  // as tall as the tallest stack: a swarm stands up as a column, a spread of people lies flat
  const used = Math.max(3, ...dots.map((d) => d.row + 1));
  const w = cols * PITCH, h = used * PITCH;
  const cx = (col: number) => (col + 0.5) * PITCH;
  const cy = (row: number) => h - (row + 0.5) * PITCH;
  const fill = (d: (typeof dots)[0]) => (d.group >= 0 ? GROUP_FILLS[Math.min(d.group, GROUP_FILLS.length - 1)] : d.burst ? "var(--vc)" : "var(--sw-dot)");
  // own words first, so copy-paste groups and the burst draw on top
  const marks = dots.map((d) => d.boost
    ? `<circle cx="${cx(d.col)}" cy="${cy(d.row)}" r="${PITCH * 0.26}" fill="none" stroke="${fill(d)}" stroke-width="${PITCH * 0.13}"/>`
    : `<circle cx="${cx(d.col)}" cy="${cy(d.row)}" r="${PITCH * 0.38}" fill="${fill(d)}"/>`).join("");
  const top = burst ? Math.max(...dots.filter((d) => d.col >= burst[0] && d.col <= burst[1]).map((d) => d.row + 1)) : 0;
  const band = burst ? `<rect class="sw-band" x="${burst[0] * PITCH}" y="${h - top * PITCH}" width="${(burst[1] - burst[0] + 1) * PITCH}" height="${top * PITCH}"/>` : "";
  const times = points.map((p) => p.t);
  const first = Number.isFinite(epoch(report.first_at)) ? epoch(report.first_at) : Math.min(...times);
  const last = Number.isFinite(epoch(report.last_at)) ? epoch(report.last_at) : Math.max(...times);
  const [from, to] = axisLabels(first, last);
  return `<figure class="sw-plot">
    <svg viewBox="0 -2 ${w} ${h + 4}" role="img" aria-label="${esc(swarmAria(report))}" preserveAspectRatio="xMidYMax meet">${band}<line class="sw-base" x1="0" x2="${w}" y1="${h + 1}" y2="${h + 1}"/>${marks}</svg>
    <figcaption class="sw-axis" aria-hidden="true"><span>${esc(from)}</span><span>${esc(to)}</span></figcaption>
  </figure>`;
}

/** The swarm strip: the dot timeline, the verdict word, up to four chips, the basis note (not on the
 *  live picture's own page, `stack`: there every post is the live feed's, and the chips already count them). */
export function swarmStrip(report: SwarmReport, opts: { live?: string | null; stack?: boolean } = {}): string {
  const v = VERDICT[report.verdict] ?? VERDICT.unclear;
  const chips = swarmChips(report);
  const why = report.verdict === "unclear" && report.why_unclear?.trim() ? `<p class="sw-why">${esc(report.why_unclear.trim())}</p>` : "";
  const note = !opts.stack && report.basis_note?.trim() ? `<p class="sw-note">${esc(report.basis_note.trim())}</p>` : "";
  return `<section class="st-sec sw${opts.stack ? " stack" : ""}" data-verdict="${esc(report.verdict)}" style="--vc:${v.css}" aria-labelledby="sw-word">
    <h2 class="sw-word" id="sw-word">${esc(v.word)}</h2>
    ${plot(report)}
    <div class="sw-say">
      ${chips.length ? `<ul class="sw-chips">${chips.map((c) => `<li>${c.label ? `<b>${esc(c.label)}</b>` : ""}${esc(c.summary)}</li>`).join("")}</ul>` : why}
      ${note}
      ${opts.live ? `<a class="sw-live" href="${esc(swarmHref(opts.live))}" data-swarm="${esc(opts.live)}">Live on Bluesky →</a>` : ""}
    </div>
  </section>`;
}

// ---------------------------------------------------------------- home: the wall

function tile(card: SwarmCard): string {
  const v = VERDICT[card.verdict] ?? VERDICT.unclear;
  return `<a class="sw-tile" href="${esc(swarmHref(card.id))}" data-swarm="${esc(card.id)}" style="--vc:${v.css}" aria-label="${esc(`${v.word}: ${card.n_accounts} accounts`)}">
    <img src="${esc(card.thumb)}" alt="" loading="lazy" decoding="async" referrerpolicy="no-referrer" draggable="false">
    <b>${esc(String(card.n_accounts))}</b>
  </a>`;
}

/** "Spreading now": square thumbnails of pictures many Bluesky accounts posted, in the API's order;
 *  each badge's colour is its verdict. Nothing at all when the list is empty or the API does not answer. */
export async function mountSwarmWall(home: HTMLElement): Promise<void> {
  const cards = await fetchSwarmWall(24);
  if (!cards.length || !home.isConnected || home.classList.contains("out")) return;
  const el = document.createElement("section");
  el.className = "sw-wall";
  el.setAttribute("aria-labelledby", "sw-wall-h");
  el.innerHTML = `<h2 id="sw-wall-h">Spreading now</h2><div class="sw-tiles">${cards.map(tile).join("")}</div>`;
  // a picture that will not load takes its tile with it; no tiles left, no wall
  el.addEventListener("error", (event) => {
    const img = event.target;
    if (!(img instanceof HTMLImageElement)) return;
    img.closest(".sw-tile")?.remove();
    if (!el.querySelector(".sw-tile")) { el.remove(); home.classList.remove("has-wall"); }
  }, true);
  home.appendChild(el);
  home.classList.add("has-wall");
  placeWall(home, el);
  // the tiles' size follows the width, the hero's height follows "Simulated examples" opening
  const hero = home.querySelector<HTMLElement>(".home-c");
  const watch = new ResizeObserver(() => (home.isConnected && el.isConnected ? placeWall(home, el) : watch.disconnect()));
  watch.observe(home);
  if (hero) watch.observe(hero);
}

/** how much of the first row of tiles shows on the first screen: enough to read as pictures, and
 *  to say there is more below without a word */
const PEEK = 0.45;

/** The wall sits over the bottom of the first screen, the heading and the top of the first row in
 *  view; never over the hero (the search box does not move for it), and the painting's credit lifts
 *  above it. Positions are in the home's scroll content, as the wall is absolute in it. */
function placeWall(home: HTMLElement, el: HTMLElement): void {
  const first = el.querySelector<HTMLElement>(".sw-tile");
  if (!first) return;
  const hero = home.querySelector<HTMLElement>(".home-c");
  const below = hero ? hero.offsetTop + hero.offsetHeight : 0;
  const top = Math.round(Math.max(home.clientHeight - (first.offsetTop + first.offsetHeight * PEEK), below));
  el.style.top = `${top}px`;
  const credit = home.querySelector<HTMLElement>(".credit");
  const lift = credit ? Math.max(0, credit.offsetTop + credit.offsetHeight - top + 6) : 0;
  home.style.setProperty("--sw-lift", `${lift}px`);
}

// ---------------------------------------------------------------- the page of one live picture

/** a picture this page can read as bytes (to trace it): its own origin, or a data/blob address.
 *  Bluesky's image CDN sends no CORS header, so its pictures cannot be fetched from here. */
function readable(url: string): boolean {
  if (/^(data|blob):/i.test(url)) return true;
  try { return new URL(url, location.href).origin === location.origin; } catch { return false; }
}

/** the picture as a file the upload path takes (JPEG, PNG, WebP, GIF); anything else is redrawn as a PNG */
async function pictureFile(url: string, signal: AbortSignal): Promise<File> {
  const r = await fetch(url, { signal });
  if (!r.ok) throw new Error(`picture ${r.status}`);
  const blob = await r.blob();
  if (IMAGE_TYPES.includes(blob.type)) return new File([blob], "picture", { type: blob.type });
  const img = new Image();
  img.src = URL.createObjectURL(blob);
  try {
    await img.decode();
    const canvas = Object.assign(document.createElement("canvas"), { width: img.naturalWidth || 600, height: img.naturalHeight || 600 });
    canvas.getContext("2d")!.drawImage(img, 0, 0, canvas.width, canvas.height);
    const png = await new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, "image/png"));
    if (!png) throw new Error("unreadable picture");
    return new File([png], "picture.png", { type: "image/png" });
  } finally {
    URL.revokeObjectURL(img.src);
  }
}

function postRow(post: SwarmDetail["posts"][0]): string {
  const words = firstWords(post.text, 9);
  const handle = post.handle ? `<span class="sw-h">${esc(post.handle)}</span>` : "";
  // a picture posted without words: the handle takes the line (no lone dot far from its handle)
  const line = words ? `<span class="sw-t">${esc(words)}</span>${handle}` : handle || `<span class="sw-t">·</span>`;
  return `<li><a href="${esc(post.url)}" target="_blank" rel="noopener noreferrer"><time>${esc(postStamp(post.at))}</time>${line}</a></li>`;
}

export function swarmPageHtml(detail: SwarmDetail, canTrace: boolean): string {
  const lines = (detail.caption ?? "").split("\n").map((line) => line.trim()).filter(Boolean).slice(0, 4);
  const posts = (detail.posts ?? []).filter((post) => post && /^https?:\/\//i.test(post.url)).slice(0, 30);
  const SHOWN = 8;
  // the list holds at most 30 links; the count is every post of the picture, as the chips count them
  const total = Math.max(posts.length, Number.isFinite(detail.n_posts) ? detail.n_posts : 0);
  return `<div class="st-wrap">
    <button class="btn ghost sw-back" type="button" data-swarm-back>${icon.arrowL}<span>Back</span></button>
    <section class="st-hero sw-hero">
      <figure class="st-mine"><img src="${esc(detail.picture)}" alt="${esc(lines.join(" ") || "The picture")}" referrerpolicy="no-referrer" draggable="false"></figure>
      <div class="st-say">
        ${swarmStrip(detail.report, { stack: true })}
        ${canTrace ? `<div class="st-actions"><button class="btn solid" type="button" data-swarm-trace>Trace it</button></div>` : ""}
      </div>
    </section>
    ${posts.length ? `<section class="st-sec" aria-labelledby="sw-posts-h"><h2 id="sw-posts-h">Posts<span>${total}</span></h2>
      <ol class="sw-posts">${posts.slice(0, SHOWN).map(postRow).join("")}</ol>
      ${posts.length > SHOWN ? `<details class="sw-more"><summary>+${posts.length - SHOWN}</summary><ol class="sw-posts">${posts.slice(SHOWN).map(postRow).join("")}</ol></details>` : ""}
    </section>` : ""}
  </div>`;
}

const TRACE_TIMEOUT_MS = 15000;

/** The page of one live picture over the map, in the story's layer. `onTrace` gets the picture as a
 *  file. `onLink` gets the id of a plain click on a wall tile or "Live on Bluesky" (anywhere on the
 *  page), so the caller opens it in-app; a click with a modifier key opens the link as usual. */
export function mountSwarmPage(app: HTMLElement, onTrace: (file: File) => void, onLink: (id: string) => void, onBack: () => void) {
  const el = document.createElement("section");
  el.className = "story sw-page";
  el.setAttribute("aria-label", "Live picture");
  el.hidden = true;
  el.tabIndex = -1;
  app.appendChild(el);
  let shown: SwarmDetail | null = null;
  document.addEventListener("click", (event) => {
    if (event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
    const link = (event.target as HTMLElement).closest<HTMLAnchorElement>("a[data-swarm]");
    if (!link?.dataset.swarm) return;
    event.preventDefault();
    onLink(link.dataset.swarm);
  });
  el.addEventListener("click", async (event) => {
    if ((event.target as HTMLElement).closest("[data-swarm-back]")) return onBack();
    const button = (event.target as HTMLElement).closest<HTMLButtonElement>("[data-swarm-trace]");
    const detail = shown;
    if (!button || !detail) return;
    button.disabled = true;
    const ctl = new AbortController();
    const timer = setTimeout(() => ctl.abort(), TRACE_TIMEOUT_MS);
    try {
      const file = await pictureFile(detail.picture, ctl.signal);
      if (shown === detail && !el.hidden) onTrace(file); // the reader may have gone Back meanwhile
    } catch {
      if (ctl.signal.aborted) button.disabled = false; // too slow this time: it can be tried again
      else button.closest(".st-actions")?.remove(); // unreadable after all: no button rather than an error
    } finally {
      clearTimeout(timer);
    }
  });
  el.addEventListener("error", (event) => {
    if (!(event.target instanceof HTMLImageElement)) return;
    event.target.replaceWith(Object.assign(document.createElement("span"), { className: "st-noimg", textContent: "No picture" }));
    el.querySelector("[data-swarm-trace]")?.closest(".st-actions")?.remove(); // nothing left to trace
  }, true);
  return {
    /** "missing" when the picture is not there (404, API down); "stale" when `current()` says the
     *  reader opened something else while it loaded (nothing is shown then) */
    async open(id: string, current: () => boolean = () => true): Promise<"shown" | "missing" | "stale"> {
      const detail = await fetchSwarmDetail(id);
      if (!current()) return "stale";
      if (!detail) return "missing";
      shown = detail;
      el.innerHTML = swarmPageHtml(detail, readable(detail.picture));
      el.hidden = false;
      app.dataset.story = "story";
      el.scrollTop = 0;
      el.focus();
      return "shown";
    },
    isOpen: () => !el.hidden,
    hide() {
      if (el.hidden) return;
      el.hidden = true;
      el.innerHTML = "";
      shown = null;
      if (app.dataset.story === "story" && !app.querySelector(".story:not(.sw-page):not([hidden])")) delete app.dataset.story;
    },
  };
}
// Meme swarms: is one picture being pushed by a swarm (bot network, astroturfing, brigading)?
// The types mirror swarm/model.py field for field (that file is the contract: change both together).
// Below them, the pure logic the UI draws from (dot layout, chips, labels: tested in
// tests/test_trackdown_swarm.mjs) and the two reads of the API. Nothing here touches the DOM.

export type SwarmPlatform = "bluesky" | "x" | "web";
export type SwarmFamily = "timing" | "accounts" | "copy" | "boost";
/** swarm -> "Shill", organic -> "Chill", unclear -> "Can't tell": about the group of posts, never one account */
export type SwarmVerdict = "swarm" | "organic" | "unclear";
export type SwarmBasis = "live" | "sample";
export type SwarmAction = "post" | "repost" | "quote" | "reply" | "like";

export interface SwarmSignal {
  family: SwarmFamily;
  name: string;
  score: number; // 0..1
  polarity: "for" | "against";
  /** a few plain words with the numbers, shown as is: "31 accounts in 4 min" */
  summary: string;
  numbers: Record<string, number | string | null>;
  examples: string[];
}

export interface SwarmBurst { start: string; end: string; n_posts: number; n_accounts: number }

export interface SwarmTimelinePoint {
  t: number; // epoch seconds
  a: number; // account index within the report; not a name
  k: SwarmAction;
  g: number; // same-words group; 0 = own words
  burst: boolean;
}

export interface SwarmReport {
  verdict: SwarmVerdict;
  why_unclear: string;
  score: number;
  guard: number;
  p_value: number | null;
  families: Partial<Record<SwarmFamily, number>>;
  fired: SwarmFamily[];
  signals: SwarmSignal[]; // strongest first, guards last
  n_posts: number;
  n_boosts: number;
  n_accounts: number;
  n_accounts_known: number;
  first_at: string | null;
  last_at: string | null;
  burst: SwarmBurst | null;
  timeline: SwarmTimelinePoint[]; // <= 300, time order
  basis: SwarmBasis;
  basis_note: string;
  version: string;
}

export interface SwarmPost { url: string; platform: SwarmPlatform; handle: string | null; at: string | null; text: string }

export interface SwarmCard {
  id: string;
  thumb: string;
  verdict: SwarmVerdict;
  score: number;
  n_posts: number;
  n_accounts: number;
  first_at: string | null;
  last_at: string | null;
  families: Partial<Record<SwarmFamily, number>>;
  headline: string;
  kind: string | null;
}

export interface SwarmDetail extends SwarmCard {
  picture: string;
  report: SwarmReport;
  posts: SwarmPost[]; // <= 30, earliest first
  caption: string | null;
}

export interface SwarmWall { items: SwarmCard[]; as_of: string | null; window_h: number | null }

/** The swarm page's Back control: "history" when the app opened the page over one of its own
 *  screens (a wall tile, "Live on Bluesky": main.ts pushes `{ swarm, inApp: true }`), so the
 *  browser's Back restores that screen exactly; "home" when it was opened from a link. */
export function swarmBackTarget(state: unknown): "history" | "home" {
  return !!state && typeof state === "object" && (state as { inApp?: unknown }).inApp === true ? "history" : "home";
}

/** a lookup's pointer to the live Bluesky group of the same picture (its page is ?swarm=<id>) */
export interface SwarmLiveRef { id: string; verdict: SwarmVerdict; n_accounts: number }

// ---------------------------------------------------------------- words and colours

export const VERDICT: Record<SwarmVerdict, { word: string; css: string }> = {
  swarm: { word: "Shill", css: "var(--shill)" },
  organic: { word: "Chill", css: "var(--chill)" },
  unclear: { word: "Can't tell", css: "var(--unsure)" },
};
export const FAMILY_NAME: Record<SwarmFamily, string> = { timing: "Timing", accounts: "Accounts", copy: "Copy-paste", boost: "Boosting" };

/** fills for same-words groups, largest group first (the painting's other colours, none of the verdict ones) */
export const GROUP_FILLS = ["#e4b36a", "#7aa2f0", "#b9a6e3", "#f2efe9"];

export interface SwarmChip { family: SwarmFamily; label: string; summary: string; score: number }

/** What the verdict rests on, as at most `max` chips. Shill: the strongest "for" signal of each
 *  family that fired. Chill: the strongest "against" signals, unlabelled. Can't tell: none (why_unclear says it). */
export function swarmChips(report: Pick<SwarmReport, "verdict" | "signals" | "fired">, max = 4): SwarmChip[] {
  if (report.verdict === "unclear") return [];
  const signals = (report.signals ?? []).filter((s) => s && s.summary?.trim() && Number.isFinite(s.score));
  const chip = (s: SwarmSignal): SwarmChip => ({ family: s.family, label: FAMILY_NAME[s.family] ?? s.family, summary: s.summary.trim(), score: s.score });
  const byScore = (a: SwarmSignal, b: SwarmSignal) => b.score - a.score;
  if (report.verdict === "organic") {
    // no family label: a guard's family names what it rules out ("Copy-paste" over "14 of 18 own words")
    const seen = new Set<string>();
    return signals.filter((s) => s.polarity === "against").sort(byScore)
      .filter((s) => !seen.has(s.summary.trim()) && !!seen.add(s.summary.trim())).slice(0, max).map((s) => ({ ...chip(s), label: "" }));
  }
  const fired = new Set(report.fired ?? []);
  const best = new Map<SwarmFamily, SwarmSignal>();
  for (const s of signals) {
    if ((s.polarity ?? "for") !== "for") continue;
    if (fired.size && !fired.has(s.family)) continue;
    const held = best.get(s.family);
    if (!held || s.score > held.score) best.set(s.family, s);
  }
  return [...best.values()].sort(byScore).slice(0, max).map(chip);
}

// ---------------------------------------------------------------- the dot timeline

export interface SwarmDot {
  col: number;
  row: number; // 0 = bottom
  t: number;
  boost: boolean; // repost, like, quote, reply
  burst: boolean;
  /** -1: own words; 0..: rank of its same-words group by size (0 = the biggest copy-paste) */
  group: number;
}
export interface SwarmLayout { dots: SwarmDot[]; cols: number; rows: number; burst: [number, number] | null }

/**
 * One dot per sighting, packed into `cols` columns of at most `rows` dots (a histogram that keeps
 * its dots). x is time on a gap-compressed axis: each gap between two sightings counts
 * log(1 + gap / tau), so a day-long wait does not squeeze everything else into one column and a
 * spread of ordinary people stays scattered, while sightings seconds apart land in the same column.
 * Dots fill columns in time order and spill into the next column when one is full, so a burst
 * becomes a solid block. Nothing moves left of an earlier sighting.
 */
export function layoutTimeline(points: readonly SwarmTimelinePoint[], opts: { cols?: number; rows?: number; tau?: number } = {}): SwarmLayout {
  const cols = Math.max(1, Math.floor(opts.cols ?? 48));
  const tau = opts.tau ?? 60;
  const pts = points.filter((p) => p && Number.isFinite(p.t)).slice().sort((a, b) => a.t - b.t);
  const n = pts.length;
  const rows = Math.max(1, Math.floor(opts.rows ?? 10), Math.ceil(n / cols));
  if (!n) return { dots: [], cols, rows, burst: null };

  const pos = [0];
  for (let i = 1; i < n; i++) pos.push(pos[i - 1] + Math.log1p(Math.max(0, pts[i].t - pts[i - 1].t) / tau));
  const total = pos[n - 1];
  // Everything within half an hour is not stretched across the whole width: the axis is then at least
  // as long as four hour-long gaps, so posts seconds apart (5 accounts in 2 s) stay one block, centred
  // below, instead of looking like people who posted all day. Longer spans reach both ends.
  const short = pts[n - 1].t - pts[0].t < 1800;
  const span = short ? Math.max(total, 4 * Math.log1p(3600 / tau)) : total;
  const compact = total < span;
  const target = pos.map((p) => Math.round((p / span) * (cols - 1)));

  // forward: never left of the previous sighting, at most `rows` per column
  const col = new Array<number>(n);
  let cur = -1, count = 0;
  for (let i = 0; i < n; i++) {
    let c = Math.max(target[i], cur);
    if (c === cur && count >= rows) c = cur + 1;
    if (c !== cur) { cur = c; count = 0; }
    col[i] = c;
    count++;
  }
  // backward: whatever spilled past the right edge is pushed back in (n <= cols * rows, so it fits)
  if (col[n - 1] > cols - 1) {
    cur = cols - 1; count = 0;
    for (let i = n - 1; i >= 0; i--) {
      let c = Math.min(col[i], cur);
      if (c === cur && count >= rows) c = cur - 1;
      if (c !== cur) { cur = c; count = 0; }
      col[i] = c;
      count++;
    }
  }
  if (compact) {
    const shift = Math.floor((cols - 1 - (col[n - 1] - col[0])) / 2) - col[0];
    for (let i = 0; i < n; i++) col[i] += shift;
  }

  // same-words groups ranked by size, biggest first; ties by first appearance
  const sizes = new Map<number, number>();
  for (const p of pts) if (p.g > 0) sizes.set(p.g, (sizes.get(p.g) ?? 0) + 1);
  const rank = new Map([...sizes.entries()].sort((a, b) => b[1] - a[1]).map(([g], i) => [g, i]));

  const dots = pts.map((p, i): SwarmDot => ({ col: col[i], row: 0, t: p.t, boost: p.k !== "post", burst: !!p.burst, group: p.g > 0 ? rank.get(p.g)! : -1 }));
  // inside a column (seconds apart) the order is free: stack copy-paste groups at the bottom, biggest
  // first, then own words, then boosts, so a group reads as one band of one colour across a burst
  const order = (d: SwarmDot) => (d.boost ? 2e6 : 0) + (d.group >= 0 ? d.group : 1e6);
  const byCol = new Map<number, SwarmDot[]>();
  for (const d of dots) byCol.set(d.col, [...(byCol.get(d.col) ?? []), d]);
  for (const stack of byCol.values()) stack.sort((a, b) => order(a) - order(b) || a.t - b.t).forEach((d, row) => (d.row = row));
  const inBurst = dots.filter((d) => d.burst).map((d) => d.col);
  return { dots, cols, rows, burst: inBurst.length ? [Math.min(...inBurst), Math.max(...inBurst)] : null };
}

// ---------------------------------------------------------------- labels

const plural = (n: number, word: string) => `${n} ${word}${n === 1 ? "" : "s"}`;
/** a duration in words for screen readers: "4 minutes", "2 hours", "3 days" */
export function durationWords(seconds: number): string {
  const s = Math.max(0, Math.round(seconds));
  if (s < 90) return plural(Math.max(1, s), "second");
  const m = Math.round(s / 60);
  if (m < 90) return plural(m, "minute");
  const h = Math.round(s / 3600);
  if (h < 48) return plural(h, "hour");
  return plural(Math.round(s / 86400), "day");
}
/** the same, short, for the axis: "4 min", "2 h", "3 d" */
export function durationShort(seconds: number): string {
  const s = Math.max(0, Math.round(seconds));
  if (s < 90) return `${s} s`;
  const m = Math.round(s / 60);
  if (m < 90) return `${m} min`;
  const h = s / 3600;
  if (h < 48) return `${h < 10 ? h.toFixed(1).replace(/\.0$/, "") : Math.round(h)} h`;
  return `${Math.round(s / 86400)} d`;
}

const epoch = (iso: string | null | undefined) => {
  const t = iso ? Date.parse(iso) / 1000 : NaN;
  return Number.isFinite(t) ? t : null;
};

/** "Shill: 31 accounts in 4 minutes": the plot's accessible name */
export function swarmAria(report: Pick<SwarmReport, "verdict" | "n_accounts" | "burst" | "first_at" | "last_at" | "timeline">): string {
  const word = VERDICT[report.verdict]?.word ?? VERDICT.unclear.word;
  const b = report.burst;
  const bs = epoch(b?.start), be = epoch(b?.end);
  if (b && bs != null && be != null && b.n_accounts > 1) return `${word}: ${plural(b.n_accounts, "account")} in ${durationWords(be - bs)}`;
  const times = (report.timeline ?? []).map((p) => p.t).filter(Number.isFinite);
  const first = epoch(report.first_at) ?? (times.length ? Math.min(...times) : null);
  const last = epoch(report.last_at) ?? (times.length ? Math.max(...times) : null);
  const accounts = plural(report.n_accounts, "account");
  return first != null && last != null && last > first ? `${word}: ${accounts} over ${durationWords(last - first)}` : `${word}: ${accounts}`;
}

const p2 = (n: number) => String(n).padStart(2, "0");
const MON = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
/** a moment as UTC clock time, with the day when it is not today (UTC, like ui/format.ts): "14:12",
 *  "13 Nov 22:30". Empty for a missing or unreadable time. */
export function utcStamp(seconds: number, now = Date.now() / 1000): string {
  if (!Number.isFinite(seconds)) return "";
  const d = new Date(seconds * 1000);
  const today = new Date(now * 1000);
  const clock = `${p2(d.getUTCHours())}:${p2(d.getUTCMinutes())}`;
  const sameDay = d.getUTCFullYear() === today.getUTCFullYear() && d.getUTCMonth() === today.getUTCMonth() && d.getUTCDate() === today.getUTCDate();
  return sameDay ? clock : `${d.getUTCDate()} ${MON[d.getUTCMonth()]} ${clock}`;
}

/** a post's time for its row: `utcStamp` of an ISO time, empty when missing */
export const postStamp = (iso: string | null | undefined, now = Date.now() / 1000) => utcStamp(epoch(iso) ?? NaN, now);

/** the two axis labels: the first sighting's UTC clock time (with the day when it is not today) and
 *  how long after it the last one came */
export function axisLabels(first: number, last: number, now = Date.now() / 1000): [string, string] {
  return [utcStamp(first, now), last > first ? `+${durationShort(last - first)}` : ""];
}

/** the first few words of a post, for a one-line link */
export function firstWords(text: string, words = 8): string {
  const parts = (text ?? "").replace(/\s+/g, " ").trim().split(" ").filter(Boolean);
  return parts.slice(0, words).join(" ") + (parts.length > words ? "…" : "");
}

// ---------------------------------------------------------------- reads

/** the development mock (`?mockSwarm`, dev server only) */
const mocked = () => import.meta.env.DEV && new URLSearchParams(location.search).has("mockSwarm");

async function getJson<T>(url: string, ms = 8000): Promise<T | null> {
  const ctl = new AbortController();
  const timer = setTimeout(() => ctl.abort(), ms);
  try {
    const r = await fetch(url, { signal: ctl.signal, headers: { accept: "application/json" } });
    if (!r.ok || !(r.headers.get("content-type") ?? "").includes("json")) return null;
    return (await r.json()) as T;
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
}

/** GET /api/swarms: the wall. Any failure is an empty wall (the home then shows nothing). */
export async function fetchSwarmWall(limit = 24): Promise<SwarmCard[]> {
  const wall = mocked() ? (await import("./mockSwarm")).mockWall() : await getJson<SwarmWall>(`/api/swarms?limit=${limit}`);
  return Array.isArray(wall?.items) ? wall.items.filter((c) => c && typeof c.id === "string" && typeof c.thumb === "string").slice(0, limit) : [];
}

/** GET /api/swarms/{id}; null when it is missing or the API is down */
export async function fetchSwarmDetail(id: string): Promise<SwarmDetail | null> {
  const detail = mocked() ? (await import("./mockSwarm")).mockDetail(id) : await getJson<SwarmDetail>(`/api/swarms/${encodeURIComponent(id)}`);
  return detail && typeof detail.picture === "string" && detail.report ? detail : null;
}
